import React, { useState } from "react";

export default function LiveDemoPage() {
  const [detection, setDetection] = useState({
    rgb: true,
    thermal: false,
    depth: true,
    map: false,
  });

  return (
    <div className="min-h-screen bg-black text-white font-sans p-6">
      <h1 className="text-3xl font-bold text-cyan-400 mb-4 text-center">ADI Drone – Live Demo</h1>

      {/* Camera Feeds Grid */}
      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-2 gap-4 mb-10">
        <div
          className={`aspect-video bg-black border-4 rounded-xl flex items-center justify-center shadow-xl transition-all duration-300 ${
            detection.rgb
              ? "border-cyan-400 text-cyan-300 shadow-cyan-500/20 animate-pulse"
              : "border-gray-700 text-gray-400"
          }`}
        >
          RGB Feed (People Detection)
        </div>
        <div
          className={`aspect-video bg-black border-4 rounded-xl flex items-center justify-center shadow-xl transition-all duration-300 ${
            detection.thermal
              ? "border-orange-400 text-orange-300 shadow-orange-500/20 animate-pulse"
              : "border-gray-700 text-gray-400"
          }`}
        >
          Thermal View (Heat Signature)
        </div>
        <div
          className={`aspect-video bg-black border-4 rounded-xl flex items-center justify-center shadow-xl transition-all duration-300 ${
            detection.depth
              ? "border-blue-400 text-blue-300 shadow-blue-500/20 animate-pulse"
              : "border-gray-700 text-gray-400"
          }`}
        >
          Depth Map View
        </div>
        <div
          className={`aspect-video bg-black border-4 rounded-xl flex items-center justify-center shadow-xl transition-all duration-300 ${
            detection.map
              ? "border-green-400 text-green-300 shadow-green-500/20 animate-pulse"
              : "border-gray-700 text-gray-400"
          }`}
        >
          Map View (GPS Tracking)
        </div>
      </div>

      {/* Toggle Buttons */}
      <div className="text-center my-6 space-x-4">
        <button
          onClick={() => setDetection({ ...detection, rgb: !detection.rgb })}
          className="px-4 py-2 bg-cyan-500 rounded hover:bg-cyan-600 transition"
        >
          Toggle RGB Detection
        </button>
        <button
          onClick={() => setDetection({ ...detection, thermal: !detection.thermal })}
          className="px-4 py-2 bg-orange-500 rounded hover:bg-orange-600 transition"
        >
          Toggle Thermal
        </button>
        <button
          onClick={() => setDetection({ ...detection, depth: !detection.depth })}
          className="px-4 py-2 bg-blue-500 rounded hover:bg-blue-600 transition"
        >
          Toggle Depth
        </button>
        <button
          onClick={() => setDetection({ ...detection, map: !detection.map })}
          className="px-4 py-2 bg-green-500 rounded hover:bg-green-600 transition"
        >
          Toggle Map
        </button>
      </div>

      {/* Alerts Panel */}
      <div className="bg-gray-800 p-4 rounded-xl shadow-lg max-w-4xl mx-auto">
        <h2 className="text-xl text-cyan-300 mb-3">Live Detection Logs</h2>
        <ul className="space-y-2 text-sm text-gray-300">
          <li>🔥 Fire detected near Zone 3 at 12:05 PM</li>
          <li>🧍‍♂️ 6 people detected in Zone 1</li>
          <li>🤕 Injured person detected – fall posture confirmed</li>
          <li>📍 Drone heading: North-East | Location: 22.5726° N, 88.3639° E</li>
          <li>🎤 Screaming detected – potential panic situation</li>
        </ul>
      </div>
    </div>
  );
}
